def fizzbuzz(n: int) -> list[str]:
    """Devuelve una lista de strings del 1 al n, donde los multiplos de 3 son 'Fizz',
    los de 5 'Buzz' y los de ambos 'FizzBuzz'. El resto es el número como string."""
    result: list[str] = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

from typing import List


def aplanar(lista: List) -> List:
    """
    Recibe una lista con sublistas anidadas a cualquier profundidad
    y devuelve una lista plana con todos los elementos.
    """
    if not lista:
        return []
    if len(lista) == 1 and isinstance(lista[0], list):
        return aplanar(lista[0])
    return [elem for sublist in lista for elem in sublist]

def buscar(lista: list, x) -> int:
    """
    Realiza una búsqueda binaria sobre una lista ordenada
    y devuelve el índice de x, o -1 si no está en la lista.
    """
    if not lista:
        return -1

    left = 0
    right = len(lista) - 1

    while left <= right:
        mid = (left + right) // 2
        if lista[mid] == x:
            return mid
        elif lista[mid] < x:
            left = mid + 1
        else:
            right = mid - 1

    return -1

