from typing import Optional


def mayor_racha(lista: list) -> Optional[tuple]:
    """
    Encuentra la racha más larga de elementos consecutivos iguales
    y devuelve la tupla (elemento, longitud).
    Si hay empate, devuelve la primera.
    Con lista vacia devuelve None.
    """
    if not lista:
        return None

    max_racha = [1, lista[0]]  # [longitud, elemento]

    for i in range(1, len(lista)):
        if lista[i] == lista[i - 1]:
            current_length = i - i + 1
            if current_length > max_racha[0]:
                max_racha = [current_length, lista[i]]
        else:
            max_racha[0] = max(max_racha[0], i - i + 1)

    return max_racha[1]

def a_camel(s: str) -> str:
    """Convierte un texto a snake_case a camelCase: la primera palabra en minúscula
    y las siguientes con la inicial en mayúscula, sin guiones bajos."""
    words = s.split()
    result = []
    for i, word in enumerate(words):
        if i == 0:
            result.append(word.lower())
        else:
            result.append(word.capitalize())
    return " ".join(result)
